create table public.project_files(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),uploader_id uuid not null references public.profiles(id),file_name text not null check(length(file_name) between 1 and 255),storage_path text not null unique,size_bytes bigint not null check(size_bytes>0 and size_bytes<=10485760),created_at timestamptz not null default now());
create index on public.project_files(project_id);create index on public.project_files(uploader_id);
alter table public.project_files enable row level security;
revoke all on public.project_files from anon,authenticated;grant select,insert on public.project_files to authenticated;
create policy project_files_read on public.project_files for select to authenticated using(private.project_access(project_id));
create policy project_files_add on public.project_files for insert to authenticated with check(private.project_access(project_id) and uploader_id=auth.uid() and split_part(storage_path,'/',1)=project_id::text and split_part(storage_path,'/',2)=auth.uid()::text and exists(select 1 from public.projects where id=project_id and status not in('CLOSED','CANCELLED')) and exists(select 1 from storage.objects where bucket_id='project-files' and name=storage_path));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project-files','project-files',false,10485760,array['application/pdf','image/png','image/jpeg','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do nothing;
create policy project_storage_read on storage.objects for select to authenticated using(bucket_id='project-files' and exists(select 1 from public.projects where id::text=split_part(name,'/',1) and private.project_access(id)));
create policy project_storage_add on storage.objects for insert to authenticated with check(bucket_id='project-files' and split_part(name,'/',2)=auth.uid()::text and exists(select 1 from public.projects where id::text=split_part(name,'/',1) and private.project_access(id) and status not in('CLOSED','CANCELLED')));
create policy project_storage_orphan_cleanup on storage.objects for delete to authenticated using(bucket_id='project-files' and split_part(name,'/',2)=auth.uid()::text and not exists(select 1 from public.project_files where storage_path=name) and exists(select 1 from public.projects where id::text=split_part(name,'/',1) and private.project_access(id)));
